27	import org.springframework.http.HttpHeaders;
28	import org.springframework.http.HttpStatus;
29	import org.springframework.http.ResponseEntity;
30	import org.springframework.samples.petclinic.mapper.OwnerMapper;
31	import org.springframework.samples.petclinic.mapper.PetMapper;
32	import org.springframework.samples.petclinic.mapper.VisitMapper;
33	import org.springframework.samples.petclinic.model.Owner;
34	import org.springframework.samples.petclinic.model.Pet;
35	import org.springframework.samples.petclinic.model.Visit;
36	import org.springframework.samples.petclinic.rest.advice.DuplicateOwnerTelephoneException;
37	import org.springframework.samples.petclinic.rest.advice.InvalidOwnerFieldsException;
38	import org.springframework.samples.petclinic.rest.api.OwnersApi;
39	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
40	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
41	import org.springframework.samples.petclinic.rest.dto.PetDto;
42	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
43	import org.springframework.samples.petclinic.rest.dto.VisitDto;
44	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
45	import org.springframework.samples.petclinic.service.ClinicService;
46	import org.springframework.samples.petclinic.util.TelephoneNormalizer;
47	import org.springframework.security.access.prepost.PreAuthorize;
48	import org.springframework.web.bind.annotation.CrossOrigin;
49	import org.springframework.web.bind.annotation.RequestMapping;
50	import org.springframework.web.bind.annotation.RestController;
51	import org.springframework.web.util.UriComponentsBuilder;
52	
53	import jakarta.transaction.Transactional;
54	
55	/**
56	 * @author Vitaliy Fedoriv
57	 */
58	
59	@RestController
60	@CrossOrigin(exposedHeaders = "errors, content-type")
61	@RequestMapping("/api")
62	public class OwnerRestControllerV1 implements OwnersApi {
63	
64	    /**
65	     * Syntactic validation for an owner email: a non-empty local part, an '@', and a dotted domain
66	     * whose top-level label is at least two letters. Deliberately conservative so plainly malformed
67	     * input (e.g. a value without an '@') is rejected.
68	     */
69	    private static final Pattern EMAIL_PATTERN =
70	        Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$");
71	
72	    private final ClinicService clinicService;
73	
74	    private final OwnerMapper ownerMapper;
75	
76	    private final PetMapper petMapper;
77	
78	    private final VisitMapper visitMapper;
79	
80	    public OwnerRestControllerV1(ClinicService clinicService,
81	                                 OwnerMapper ownerMapper,
82	                                 PetMapper petMapper,
83	                                 VisitMapper visitMapper) {
84	        this.clinicService = clinicService;
85	        this.ownerMapper = ownerMapper;
86	        this.petMapper = petMapper;
87	        this.visitMapper = visitMapper;
88	    }
89	
90	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
91	    @Override
92	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
93	        Collection<Owner> owners;
94	        if (lastName != null) {
95	            owners = this.clinicService.findOwnerByLastName(lastName);
96	        } else {
97	            owners = this.clinicService.findAllOwners();
98	        }
99	        if (owners.isEmpty()) {
100	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
101	        }
102	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
103	    }
104	
105	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
106	    @Override
107	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
108	        Owner owner = this.clinicService.findOwnerById(ownerId);
109	        if (owner == null) {
110	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
111	        }
112	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
113	    }
114	
115	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
116	    @Override
117	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
118	        rejectBlankOwnerFields(ownerFieldsDto);
119	        normalizeTelephone(ownerFieldsDto);
120	        rejectDuplicateTelephone(ownerFieldsDto.getTelephone());
121	        normalizeEmail(ownerFieldsDto);
122	        HttpHeaders headers = new HttpHeaders();
123	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
124	        if (owner.getRegistrationDate() == null) {
125	            owner.setRegistrationDate(LocalDate.now());
126	        }
127	        this.clinicService.saveOwner(owner);
128	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
129	        headers.setLocation(UriComponentsBuilder.newInstance()
130	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
131	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
132	    }
133	
134	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
135	    @Override
136	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
137	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
138	        if (currentOwner == null) {
139	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
140	        }
141	        currentOwner.setAddress(ownerFieldsDto.getAddress());
142	        currentOwner.setCity(ownerFieldsDto.getCity());
143	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
144	        currentOwner.setLastName(ownerFieldsDto.getLastName());
145	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
146	        normalizeEmail(ownerFieldsDto);
147	        currentOwner.setEmail(ownerFieldsDto.getEmail());
148	        this.clinicService.saveOwner(currentOwner);
149	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
150	    }
151	
152	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
153	    @Transactional
154	    @Override
155	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
156	        Owner owner = this.clinicService.findOwnerById(ownerId);
157	        if (owner == null) {
158	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
159	        }
160	        this.clinicService.deleteOwner(owner);
161	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
162	    }
163	
164	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
165	    @Override
166	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
167	        Owner owner = this.clinicService.findOwnerById(ownerId);
168	        if (owner == null) {
169	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
170	        }
171	        HttpHeaders headers = new HttpHeaders();
172	        Pet pet = petMapper.toPet(petFieldsDto);
173	        owner.setId(ownerId);
174	        pet.setOwner(owner);
175	        pet.getType().setName(null);
176	        this.clinicService.savePet(pet);
177	        PetDto petDto = petMapper.toPetDto(pet);
178	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
179	            .buildAndExpand(pet.getId()).toUri());
180	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
181	    }
182	
183	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
184	    @Override
185	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
186	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
187	        if (currentOwner != null) {
188	            Pet currentPet = this.clinicService.findPetById(petId);
189	            if (currentPet != null) {
190	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
191	                currentPet.setName(petFieldsDto.getName());
192	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
193	                this.clinicService.savePet(currentPet);
194	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
195	            }
196	        }
197	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
198	    }
199	
200	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
201	    @Override
202	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
203	        HttpHeaders headers = new HttpHeaders();
204	        Visit visit = visitMapper.toVisit(visitFieldsDto);
205	        Pet pet = new Pet();
206	        pet.setId(petId);
207	        visit.setPet(pet);
208	        this.clinicService.saveVisit(visit);
209	        VisitDto visitDto = visitMapper.toVisitDto(visit);
210	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
211	            .buildAndExpand(visit.getId()).toUri());
212	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
213	    }
214	
215	
216	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
217	    @Override
218	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
219	        Owner owner = this.clinicService.findOwnerById(ownerId);
220	        if (owner != null) {
221	            Pet pet = owner.getPet(petId);
222	            if (pet != null) {
223	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
224	            }
225	        }
226	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
227	    }
228	
229	    /**
230	     * Rejects an owner whose {@code firstName}, {@code lastName}, {@code address}, {@code city} or
231	     * {@code telephone} is missing (null) or blank (empty or whitespace only). Bean Validation on
232	     * the request body already rejects null and empty values, but permits whitespace-only strings
233	     * for fields without a stricter pattern (e.g. {@code city}, {@code address}); this guard closes
234	     * that gap so every required field must carry a non-blank value.
235	     *
236	     * @param ownerFieldsDto the submitted owner fields
237	     * @throws InvalidOwnerFieldsException if one or more required fields are missing or blank
238	     */
239	    private void rejectBlankOwnerFields(OwnerFieldsDto ownerFieldsDto) {
240	        List<String> missing = new ArrayList<>();
241	        addIfBlank(missing, "firstName", ownerFieldsDto.getFirstName());
242	        addIfBlank(missing, "lastName", ownerFieldsDto.getLastName());
243	        addIfBlank(missing, "address", ownerFieldsDto.getAddress());
244	        addIfBlank(missing, "city", ownerFieldsDto.getCity());
245	        addIfBlank(missing, "telephone", ownerFieldsDto.getTelephone());
246	        if (!missing.isEmpty()) {
247	            throw new InvalidOwnerFieldsException(missing);
248	        }
249	    }
250	
251	    private void addIfBlank(List<String> missing, String fieldName, String value) {
252	        if (value == null || value.isBlank()) {
253	            missing.add(fieldName);
254	        }
255	    }
256	
257	    /**
258	     * Normalizes the submitted {@code telephone} on create to its canonical form (see
259	     * {@link TelephoneNormalizer#normalize}) and writes it back onto the request so it is the value
260	     * stored and returned. Any input that does not reduce to a valid telephone is rejected with a
261	     * {@code 400 Bad Request}.
262	     *
263	     * @param ownerFieldsDto the submitted owner fields (its {@code telephone} is non-blank here,
264	     *                       {@link #rejectBlankOwnerFields} having already run)
265	     * @throws InvalidOwnerFieldsException if the telephone cannot be normalized to a valid value
266	     */
267	    private void normalizeTelephone(OwnerFieldsDto ownerFieldsDto) {
268	        String normalized = TelephoneNormalizer.normalize(ownerFieldsDto.getTelephone())
269	            .orElseThrow(() -> new InvalidOwnerFieldsException(List.of("telephone")));
270	        ownerFieldsDto.setTelephone(normalized);
271	    }
272	
273	    /**
274	     * Normalizes an optionally-supplied {@code email}. When absent (null) or blank the field is left
275	     * untouched (email is optional). When present it is trimmed and, after validating that it is a
276	     * syntactically valid address, written back lower-cased so it is the value stored and returned.
277	     * Any present-but-invalid address is rejected with a {@code 400 Bad Request}.
278	     *
279	     * @param ownerFieldsDto the submitted owner fields
280	     * @throws InvalidOwnerFieldsException if the email is present but not a syntactically valid address
281	     */
282	    private void normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
283	        String email = ownerFieldsDto.getEmail();
284	        if (email == null || email.isBlank()) {
285	            return;
286	        }
287	        email = email.trim();
288	        if (!EMAIL_PATTERN.matcher(email).matches()) {
289	            throw new InvalidOwnerFieldsException(List.of("email"));
290	        }
291	        ownerFieldsDto.setEmail(email.toLowerCase(Locale.ROOT));
292	    }
293	
294	    /**
295	     * Rejects creating an owner whose normalized telephone is already used by any other owner.
296	     * Both the submitted telephone and every existing owner's stored telephone are reduced to their
297	     * {@linkplain TelephoneNormalizer#toComparisonKey comparison key} before comparison, so equality
298	     * is judged on that key alone. A match is reported as a {@code 409 Conflict}.
299	     *
300	     * @param normalizedTelephone the submitted telephone, already reduced to its canonical form by
301	     *                            {@link #normalizeTelephone}
302	     * @throws DuplicateOwnerTelephoneException if another owner already uses the same telephone
303	     */
304	    private void rejectDuplicateTelephone(String normalizedTelephone) {
305	        String comparisonKey = TelephoneNormalizer.toComparisonKey(normalizedTelephone);
306	        boolean inUse = this.clinicService.findAllOwners().stream()
307	            .map(Owner::getTelephone)
308	            .filter(Objects::nonNull)
309	            .map(TelephoneNormalizer::toComparisonKey)
310	            .anyMatch(comparisonKey::equals);
311	        if (inUse) {
312	            throw new DuplicateOwnerTelephoneException(normalizedTelephone);
313	        }
314	    }
315	}
