66	     * whose top-level label is at least two letters. Deliberately conservative so plainly malformed
67	     * input (e.g. a value without an '@') is rejected.
68	     */
69	    private static final Pattern EMAIL_PATTERN =
70	        Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$");
